 const field=(key:string,label:string,help:string,step?:number)=><label className="field" key={key}><span>{label}<code>{key}</code></span><input type="number" value={config[key]} step={step||1} min={schema.config.properties[key]?.minimum} max={schema.config.properties[key]?.maximum} onChange={e=>update(key,Number(e.target.value))}/><small>{help}</small></label>;
